-- Hexagram text group 2: compact lazy-loaded records.
return {
  ["地火明夷"] = { index="第36卦", name="地火明夷", shortName="明夷卦", subtitle="晦而转明", rating="中下卦",
  xiang="时乖运拙走不着，急忙过河拆了桥，恩人无义反为怨，凡事无功枉受劳。", summary="这个卦是异卦（下离上坤）相叠。离为明，坤为顺；离为日；坤为地。日没入地，光明受损，前途不明，环境困难，宜遵时养晦，坚守正道，外愚内慧，韬光养晦。",
  career="处于不利的环境，宜心境坦然地处置险恶的条件，增强心理素质，承受各种压力。表面柔顺小心，内心洞察事理，当离去则离去，避免灾祸，脱离危险。防患于未然，坚持逆境中奋斗。", business="认真观察言市场动态，待机行动，但须坚持商业道德，即使处于不利情况下，也要冒险向前，特别是要向南方发展，会大有收获。",
  fame="内心保持大志，行动刻苦忍耐，奋斗于逆境，自守其志，收敛聪明而不外露，于混乱中更应坚持正义，藏拙守愚。", travel="最好不要马上行动，再等待一个时期，做好充分准备。", marriage="必须全面分析对方情况，不能因小失大。注意大节。",
  decision="处在不佳的状况下，环境困难，前途不明。但若能坦处厄运，能伸能屈，前景会变光明。尤其应加强修养，隐忍行志，外愚内慧，可以遇难呈祥。如能谨慎行事，处处小心，更能有所作为。" },
  ["风火家人"] = { index="第37卦", name="风火家人", shortName="家人卦", subtitle="诚威治业", rating="下下卦",
  xiang="一朵鲜花镜中开，看着极好取不来，劝君休把镜花恋，卦若逢之主可怪。", summary="这个卦是异卦（下离上巽）相叠。离为火；巽为风。火使热气上升，成为风。一切事物皆应以内在为本，然后伸延到外。发生于内，形成于外。喻先治家而后治天下，家道正，天下安乐。",
  career="成功与否取决于家庭的情况。严格治家，防止“后院”起火出现意外事故，这是事业成功的先决条件。夫妇和睦，共同合作，必可脱贫致富。事业应由内而外，循序渐进，持之以恒，而后必有所成。", business="以治家方式用于商业活动。对待公司职工应严宽结合，以严为主。宜集中领导，主事一人，共同合作，日积月累。",
  fame="以勤苦努力和安贫乐道为主，更应有家庭的支持。家道兴盛的同时，个人的事业也就容易成功。", travel="在家千日好，外出一时难，准备充分后再行动。", marriage="和睦的家庭，是一切的基础，而妻子又是家道的根本。择妻应慎重，和乐兴家。担",
  decision="因好的家庭和妻子的支持而顺利成功，务必保持这种优势，否则，由盛转衰在顷刻之间。尤其应预防家庭变故。持家重在谦和待人，勤俭积蓄以致富。亲人相互和睦、友好。" },
  ["雷火丰"] = { index="第55卦", name="雷火丰", shortName="丰卦", subtitle="日中则斜", rating="上上卦",
  xiang="古镜昏暗好几年，一朝磨明似月圆，君子谋事逢此卦，近来运转喜自然。", summary="这个卦是异卦（下离上震）相叠，电闪雷鸣，成就巨大，喻达到顶峰，如日中天。告戒；务必注意事物向相反方面发展。治乱相因，盛衰无常，不可不警惕。",
  career="处于十分顺利的鼎盛时期，各方面都很顺利，成就很大。但务必注意开始出现的衰败症状，防微杜渐，严防骄傲自满。同时，不必盲目追求不切实际的事情，全力保持当前状况的延长。", business="由于准确地把握了市场动态，商情对自己十分有利，可以大胆发展，但一定要密切注意行情，分析信息，稍有不慎，破产可能在一夜间。一旦破产应立即总结教训寻求真诚的合作者，早日走出困境。",
  fame="经过努力和奋斗，已获得成就，应注意保持和稳步发展，切勿追求虚名。", travel="十分顺利。但应提高警惕，防止乐极生悲。", marriage="可以成功，也会美满幸福，但若一方自持条件变化而动摇，则会导致不利。",
  decision="由于个人天资聪颖，条件好，因此各方面十分顺利。但务必深刻认识人生无常的真理，一切应保持适度，切记物极必反。更不应自我封闭，陷入困境，切莫灰心。" },
  ["离为火"] = { index="第30卦", name="离为火", shortName="离卦", subtitle="附和依托", rating="中上卦",
  xiang="官人来占主高升，庄农人家产业增，生意买卖利息厚，匠艺占之大亨通。", summary="这个卦是同卦（下离上离）相叠。离者丽也，附着之意，一阴附丽，上下二阳，该卦象征火，内空外明。离为火、为明、太阳反复升落，运行不息，柔顺为心。",
  career="已快进入顶点，盛极而衰，务必总结经验教训，趋善避邪，以顺自养，居危知危，激励志气，切勿妄动。尤应求助中正的人援助，以期重振事业。", business="戒急于求成，宜兢兢业业，忧深虑远，考察市场行情，公平竞争，不可投机取巧。争取与他人密切合作。",
  fame="方向未确定之前，不可到处乱撞，应持之以恒，执意追求，虚心向有才德的长者请教。", travel="可行动，事先应准备充分，不可仓促上路。", marriage="自己寻找对象恐怕有困难，最好请可靠的朋友、长辈帮忙，不得急躁。双方应相互尊敬，最忌生邪念。",
  decision="乐天知命，顺应自然，年轻时急于上进，未能实现理想，但坚持中正、谦和，可无灾祸，时常警觉，更可化险为夷。在危难时要寻求依托，但要慎重选择对象。晚年应知天命，尤不可不顾时势而轻举妄图动。" },
  ["山火贲"] = { index="第22卦", name="山火贲", shortName="贲卦", subtitle="饰外扬质", rating="中上卦",
  xiang="近来运转锐气周，窈窕淑女君子求，钟鼓乐之大吉庆，占者逢之喜临头。", summary="这个卦是异卦（下离上艮）相叠。离为火为明；艮为山为止。文明而有节制。贲（bi）卦论述文与质的关系，以质为主，以文调节。贲，文饰、修饰。",
  career="顺利，小有成绩，宜即时总结经验，图谋更大的发展。树立信心，不计较一时的得失。追求实质性的内容，慎重诸事，不得随波逐流，寻求有实力的人物提携自己。", business="开初会遇到困难，不应灰心，宜全面分析形势，大胆开拓，勇敢地投入，联合他人，共同合作，根据市场，运转业务。",
  fame="不可过多地注重外表，而应着重于内在的素质。大胆地推荐自己，但应坚持自己的理想。", travel="慎远行。但只要准备充分，注意安全，不会出麻烦。", marriage="慎重选择，有合适者，则应迫切追求，不可三心二意，务必专一。注重对方的内在气质，勿为表面现象所欺骗。",
  decision="喜爱注重外表，缺乏追求内在气质的恒心。生性较为浮躁，好务虚名，往往因此而碰壁，或半途而废。在事实的教育下，改变不切实际的做法，明察社会和人生，会有所收敛，变得自持，注重自身修养，成全事业，中年以后会大有作为，老年仍可发挥余热。" },
  ["水火既济"] = { index="第63卦", name="水火既济", shortName="既济卦", subtitle="盛极将衰", rating="中上卦",
  xiang="金榜以上题姓名，不负当年苦用功，人逢此卦名吉庆，一切谋望大亨通。", summary="这个卦是异卦（下离上坎）相叠。坎为水，离为火，水火相交，水在火上，水势压倒火势，救火大功告成。既，已经；济，成也。既济就是事情已经成功，但终将发生变故。",
  career="处在顺利和兴旺的阶段，甚至大功已经告成。如何才能保住这种势头，是问题的关键。必须认识盛极将衰的真理，必思患预防，防微杜渐，有备可无患。同时，一定要密切注意形势，抓住有利时机，继续奋发向上，推动事业发展。", business="由于市场形势有利，已经赚得许多。但同时也预示着危机的随时出现。因此，务必小心在意，事未到，先预防，终日提防戒惧。同时，认真观察市场的变化，随时转向，开拓新市场。",
  fame="个人追求名利的基本条件已经具备。必须防止因此而变得僵化和保守，以致功亏一篑，半途而废。", travel="利于出行，途中需注意安全。", marriage="起初顺利，只中途会出现挫折。",
  decision="各方面条件都很好，环境又有利于成长。但因此反而会使自己满足，停止前进，甚至变得颓废，趋向没落。一定要不断刻苦努力，保持谦虚美德，常怀不安之心，防止不测事件发生。" },
  ["天火同人"] = { index="第13卦", name="天火同人", shortName="同人卦", subtitle="上下和同", rating="中上卦",
  xiang="心中有事犯猜疑，谋望从前不着实，幸遇明人来指引，诸般忧闷自消之。", summary="这个卦是异卦（下离上乾）相叠，乾为天，为君；离为火，为臣民百姓，上天下火，火性上升，同于天，上下和同，同舟共济，人际关系和谐，天下大同。",
  career="顺利、平安、尤其是在与他人的合作方面会十分成功，宜广泛开展人际活动，建立广泛的联系，克服狭隘的门户之见，照顾各方面的利益，求大同，存小异，坚持正确的原则，必能成就大事业。", business="以真诚合作、精诚团结的态度与同行共事，公平竞争，必可获得自己应得的利益。",
  fame="自己必须刻苦努力，尤其必要取行师长和志同道全的朋友的指教、帮助，自己虚心进取，完全能够达到目的。", travel="很平安、顺利，并可以结交新朋友，获得帮助。", marriage="多情、善交际，认识的异性朋友多，故需慎重选择，注意维护双方关系和家庭和睦。",
  decision="性格开朗、乐观，为人热情，人际关系好，社交能力强，要善于同他人合作，尤其要协调多方面的关系，要有原则性，与不良风气斗争，有魄力，敢作敢为，富有自我奉献精神，并具有统御能力，适于担任一定的负责。" },
  ["泽火革"] = { index="第49卦", name="泽火革", shortName="革卦", subtitle="顺天应人", rating="上上卦",
  xiang="苗逢旱天渐渐衰，幸得天恩降雨来，忧去喜来能变化，求谋干事遂心怀。", summary="这个卦是异卦（下离上兑）相叠。离为火、兑为泽，泽内有水。水在上而下浇，火在下而上升。火旺水干；水大火熄。二者相生亦相克，必然出现变革。变革是宇宙的基本规律。",
  career="正处在转折的关键时刻，必须密切注意各种信息，认真思考。首先巩固自己的地位，完善个人的行为。时机成熟后，立即行动，积极进行变革。但应注意动机纯正，手段正当，不保守也不妄进，事业必定发达。", business="市场竞争十分激烈。为了立于不败之地，一定要敢于大胆求新，适时改变自己的经营方向，受到挫败，马上总结经验，重新奋起，拓展商业活动。注意竞争方式。",
  fame="首先要努力提高自己，完善个人的学识和品德。同时，服从上级指挥搞好工作。二者的关系一定要得到妥善处理。", travel="十分顺利，积极活动，扩大人际关系。", marriage="可能会出现一些节外生枝的麻烦事，应冷静处理，感情专注。",
  decision="十分吉利、顺利。以自己的聪明才智，顺应形势，根据时代特点，依理而动，变革渐合时宜的事物，壮大自己的事业。但应谨慎，时机不成熟不可妄动，尤忌急功近利。行动之前应三思而行。" },
  ["地雷复"] = { index="第24卦", name="地雷复", shortName="复卦", subtitle="寓动于顺", rating="中中卦",
  xiang="马氏太公不相合，世人占之忧疑多，恩人无义反为怨，是非平地起风波。", summary="这个卦是异卦（下震上坤）相叠。震为雷、为动；坤为地、为顺，动则顺，顺其自然。动在顺中，内阳外阴，循序运动，进退自如，利于前进。",
  career="已经渡过了困难时期，开始进入积极行动的阶段。但务必抓住时机，当机立断，却不可急躁，且应时常反省个人行动，严于修身，勇往直前，可望成功。", business="可大胆投资，与志同道合的伙伴坦诚合作，打开市场，勿因挫折而退缩。更可以打入外地，坚持商业道德，循序渐进，一定会有所赢利。",
  fame="时机正在成熟，不要急于求成，继续奠定基础，机遇一旦到来，务必要抓住，必将转运。最忌自伤意志。", travel="无灾无祸，且有收获。", marriage="顺利。但切不可性急，应冷静考虑。家庭的美满幸福，靠严于律己维持。",
  decision="性格活泼，精力旺盛，但因急躁情绪会造成事业损失。一定要冷静思考，勇于改正错误，必能重振事业。此时应抓住时机，明确方向，灵活机敏，脚踏实地改变处境。一旦出现意外，宜当机立断，暂行退让。如能准确驾驶自己，努力奋斗，成就事业十分顺利。" },
  ["风雷益"] = { index="第42卦", name="风雷益", shortName="益卦", subtitle="损上益下", rating="上上卦",
  xiang="时来运转吉气发，多年枯木又开花，枝叶重生多茂盛，几人见了几人夸。", summary="这个卦是异卦（下震上巽）相叠。巽为风；震为雷。风雷激荡，其势愈强，雷愈响，风雷相助互长，交相助益。此卦与损卦相反。它是损上以益下，后者是损下以益上。二卦阐述的是损益的原则。",
  career="大胆投入，勇于支持他人事业，必相得益彰。勇敢前进，敢作敢为。只要心地善良、纯洁、谦虚，事业必定与日俱增，前程无可限量。助人宜即时，要在应急，开拓事业，内部团结一致，人心所向，树立恒心，不怕冒险犯难。", business="勿追求小利，让利于顾客，反而必获丰厚利润。切忌贪心不足。在遇到危险时应向他人求教，争取诚实的援助。",
  fame="真心实意地施惠于他人，自己必然可以得到诚心诚意的回报，并且获得支持，事业必成。", travel="有利可获。大胆外出行动。", marriage="原始资料未提供。",
  decision="心胸开阔，乐于助人。人际关系好，得到众人的支持。自己贵在树立恒心，克服三心二意。尤其要向比自己优秀的人学习，借助对方的力量，充实和发展自己。树立必要的冒险精神。平日要施善于人。因此，即使遇到危险也会得到他人救助。" },
  ["火雷噬嗑"] = { index="第21卦", name="火雷噬嗑", shortName="噬嗑卦", subtitle="刚柔相济", rating="上上卦",
  xiang="运拙如同身受饥，幸得送饭又送食，适口充腹心欢喜，忧愁从此渐消移。", summary="这个卦是异卦（下震上离）相叠。离为阴卦；震为阳卦。阴阳相交，咬碎硬物，喻恩威并施，宽严结合，刚柔相济。噬嗑（shihe）为上下颚咬合，咀嚼。",
  career="困难与阻力非常大，应以坚强的意志，果敢的行为，公正无私的态度去战胜种种厄运，争取事态好转。为了早日化险为夷，必要时可采取强硬手段，甚至诉诸法律。", business="处于不利的时候，头脑冷静，明察形势，寻求机遇，不为眼前小利所诱，不发非分之财。认真听取忠告，遵守法纪，秉公办事，不得徇私情，更警惕不得触犯刑律。",
  fame="自己的努力尚不为人所知，不可急于求成，受到挫折应看作是对自己的考验，持之以恒，必能成功。", travel="另择他日为佳。若非出门不可，务必充分准备，小心为是。", marriage="初不顺利，须有顽强精神可以取得满意的结果，不可以个的情绪左右家庭事务。",
  decision="一生不平坦，会遇到挫折和磨难，但应看作是对个人的考验，应认真总结经验教训，以更为坚强的意志，不屈不挠，继续前进。经过锻炼，各方面都会有较大的进展，终将进入光明境地，取得重大成就。" },
  ["山雷颐"] = { index="第27卦", name="山雷颐", shortName="颐卦", subtitle="纯正以养", rating="上上卦",
  xiang="太公独钓渭水河，手执丝杆忧愁多，时来又遇文王访，自此永不受折磨。", summary="这个卦是异卦（下震上艮）相叠。震为雷，艮为山。山在上而雷在下，外实内虚。春暖万物养育，依时养贤育民。阳实阴虚，实者养人，虚者为人养。自食其力。",
  career="凡事得靠个人追求，自己奋斗，而不能依赖他人。更不得用不光彩的手段谋求财物。只要遵循正道，自食其力，慎言敏行，一定会有好的机遇。这时，经过一番艰苦奋斗，能够成功。", business="不得急于求成，初仅以勉强维持生活为限。谨慎小心，循序渐进，诚以待人，真诚与他人合作，因时制宜，不断追求新的开拓方向，必要时可适当冒险。",
  fame="以丰富自身知识为目的，知足安贫，刻苦努力，成功的希望极大。", travel="应慎重，不宜过多外出。如无充分准备，仓促出行，将可能会遇到凶险。", marriage="不可急于求成。关键在于加强自己的修养。一旦选中应全力追求，尤其不可三心二意。",
  decision="注意道德修养，乐于尽力而为地去帮助他人，救人急难，不贪求不应得到的财物。因此，能受到他人的尊重，也能不断得到外来的援助，个人事业十分顺利，成功的可能性很大。尤其不可粗心大意，牢记成就大阻力也大的道理。" },
  ["水雷屯"] = { index="第3卦", name="水雷屯", shortName="屯卦", subtitle="起始维艰", rating="下下卦",
  xiang="风刮乱丝不见头，颠三倒四犯忧愁，慢从款来左顺遂，急促反惹不自由。", summary="这个卦是异卦（下震上坎）相叠，震为雷，喻动；坎为雨，喻险。雷雨交加，险象丛生，环境恶劣。“屯”原指植物萌生大地。万物始生，充满艰难险阻，然而顺时应运，必欣欣向荣。",
  career="起初多不利，必知难而进，小心翼翼，勇往直前，灵活机动，可望获得大的成功，时机到来时一定要抓住，却也不得操之太急，且仍有困难，务必有他人相助，故平时应多施恩惠。", business="创业初期步履艰难，多有挫折。坚定信念最重要，不要为表面现象所迷惑，应积极进取，行动果断，打开出路。若仍无法摆脱困境，则应退守保全，等待机会，再展宏图。",
  fame="积极争取，主动追求，可以成功。", travel="慎重为好，有危险，宜改日动身。", marriage="好事多磨，忠贞纯洁，大胆追求，能够成功，婚姻美满。",
  decision="初始困难，但若具有坚忍不拔的毅力和锲而不舍的奋斗精神，前途不可估量，但往往不为他人理解而陷于孤独苦闷，事业会因此处于困难状态，需要得到贤德之人的帮助才能摆脱。如能以乐观主义精神处世，能取得成就。" },
  ["天雷无妄"] = { index="第25卦", name="天雷无妄", shortName="无妄卦", subtitle="无妄而得", rating="下下卦",
  xiang="飞鸟失机落笼中，纵然奋飞不能腾，目下只宜守本分，妄想扒高万不能。", summary="这个卦是异卦（下震上乾）相叠。乾为天为刚为健；震为雷为刚为动。动而健，刚阳盛，人心振奋，必有所得，但唯循纯正，不可妄行。无妄必有获，必可致福。",
  career="贵自知之明，从个人实际出发，不抱非分之想，脚踏实地，勤奋努力，检点行为，防意外灾祸。不计较得失，诚心追求，待机而动，事业必成。", business="切勿勉为其难，遵循市场规律，讲究商业道德，屏弃投机心理，勿贪暴利，经过辛勤努力，日积月累，必将成功。",
  fame="以良好的动机，刻苦努力，丢弃幻想，但问耕耘，不问收获，终将有所获。", travel="不存妄想则平安无事。为谋私利或邪念而行则大为不利，不宜行。", marriage="双方务以诚相待，绝不可抱以轻率的态度，亦不宜急于求成、顺其发展，水到渠成。",
  decision="精力充沛，富有上进心，可有作为。但务必勤勉努力，诚心诚恳，奋发向上，刻苦钻研。不可因小有成就而得意忘形。不必追求所得，而应追求实干。遵循规律办事，等待时机再行动。尤其应清除非份的念头。这样，可实现自己的理想。" },
  ["泽雷随"] = { index="第17卦", name="泽雷随", shortName="随卦", subtitle="随时变通", rating="中中卦",
  xiang="泥里步踏这几年，推车靠崖在眼前，目下就该再使力，扒上崖去发财源。", summary="这个卦是异卦（下震上兑）相叠，震为雷、为动；兑为悦。动而悦就是“随”。随指相互顺从，己有随物，物能随己，彼此沟通。随必依时顺势，有原则和条件，以坚贞为前提。",
  career="对社会和人生有正确的估价，重视人际关系，善于同他人合作，事业会很顺利。为了保证取得更进一步的成功，不得贪图小利，向比自己优秀的人学习，择善而从，心存诚信、努力开拓事业。", business="顺利。在与他人的真诚合作下，能够达到预期的目的。在竞争中应保持清醒头脑，从大处、长远考虑，遵守商业道德，保持至诚的态度对待顾客和同行，会保持竞争优势。",
  fame="在自己刻苦钻研的基础上，虚心向有德有才的师长学习，借助外界的力量，促使自己更快的进步，实现个人的理想。", travel="吉利。可以改变处境。", marriage="双方情投意合可以成功，家庭和睦，但若迷恋于情爱，会影响双方的事业，务必注意。",
  decision="个人成长道路并不十分顺利，但由于谦虚、随和，人际关系好，尤其能够得到长辈的器重，各种事都能在他人的帮助和关心下成功。但务必注意追随他人应有的立场和原则，不可趋炎附势，招致祸凶。" },
  ["震为雷"] = { index="第51卦", name="震为雷", shortName="震卦", subtitle="临危不乱", rating="中上卦",
  xiang="一口金钟在淤泥，人人拿着当玩石，忽然一日钟悬起，响亮一声天下知。", summary="这个卦是同卦（下震上震）相叠。震为雷，两震相叠，反响巨大，可消除沉闷之气，亨通畅达。平日应居安思危，怀恐惧心理，不敢有所怠慢，遇到突发事变，也能安然自若，谈笑如常。",
  career="处于不顺利、甚至面临危险的局面，对此务必提高警惕，有备方可无患，一旦出现突发事件，可以泰然处之，并且可以由此引吸取教训，一方面使损失减少，另一方面可以迅速复原，使事业迈上新的高度。", business="在激烈的商场竞争中，随时可能出现问题，陷入困境。冷静、从容地应付到来的现实，坚持不偏不激的中正原则，以刚毅的态度，从容不迫地去战胜困难。经过一番危机后，一定可以获得巨大利益。",
  fame="很可能会遭到挫折。不必灰心，而应自我反省，找出问题的症结所在。", travel="大胆出行，不必理会小的灾祸。", marriage="恋爱和家庭都可能出现变故，应以冷静态度处理，会有理想的结果。",
  decision="处于人生的转折关头。应正确地总结过去，为开拓新的事业奠定基础。在前进的道路上应随时心怀恐惧，勤勤恳恳，坚持正确原则，在困难中前进，命运亨通。" },
}
